/* Actual expression arithmetic: stock value corpus and malformed trap boundaries. */
#define Q3_EVAL_ENTRY EvalFixtureMain
#include "bot_eval_regression.c"
extern int PC_Evaluate(source_t *,signed long *,double *,int);
extern int PC_DollarEvaluate(source_t *,signed long *,double *,int);
static void ArithmeticValue(const char *expression,int integer,long wanted,double floating){source_t *source;long result=99;double real=99;char body[1024];snprintf(body,sizeof(body),"%s\n",expression);source=EvalStart(body);Check(PC_Evaluate(source,integer?&result:NULL,integer?NULL:&real,integer)&&!errors&&!fatals&&!numtokens&&!source->tokens&&liveOwners==4,"native arithmetic evaluates without extra owners");Check(integer?result==wanted:real==floating,"selected native arithmetic result remains exact");EvalEnd(source);}
static void ArithmeticBad(const char *expression,int integer){source_t *source;long result=99;double real=99;char body[1024];snprintf(body,sizeof(body),"%s\n",expression);source=EvalStart(body);Check(!PC_Evaluate(source,integer?&result:NULL,integer?NULL:&real,integer)&&errors>0&&!fatals&&PC_SourceHasError(source)&&!numtokens&&!source->tokens&&liveOwners==4,"invalid arithmetic rejects without undefined operation or partial owners");Check(integer?!result:!real,"failed arithmetic initializes selected output");EvalEnd(source);}
static void ArithmeticGoldens(int original){int i,j,count=0;char expression[256];for(i=-40;i<=40;i++)for(j=1;j<=8;j++){snprintf(expression,sizeof(expression),"(%d + %d) * 3 - %d",i,j,j);ArithmeticValue(expression,1,(i+j)*3-j,0);snprintf(expression,sizeof(expression),"%d / %d",i,j);ArithmeticValue(expression,1,i/j,0);snprintf(expression,sizeof(expression),"%d %% %d",i,j);ArithmeticValue(expression,1,i%j,0);snprintf(expression,sizeof(expression),"(%d < %d) && (%d != 0)",i,j,i);ArithmeticValue(expression,1,i<j&&i!=0,0);snprintf(expression,sizeof(expression),"(%d & %d) | (%d ^ %d)",i,j,i,j);ArithmeticValue(expression,1,(i&j)|(i^j),0);snprintf(expression,sizeof(expression),"%d ? %d : 3",i,j);ArithmeticValue(expression,1,i?j:3,0);count+=6;}for(i=-40;i<=40;i++)for(j=0;j<4;j++){double divisors[]={0.25,0.5,1,2};double a=i/4.0,b=divisors[j];if(original&&j<2)continue;snprintf(expression,sizeof(expression),"(%1.2f + %1.2f) * 2.0",a,b);ArithmeticValue(expression,0,0,(a+b)*2);snprintf(expression,sizeof(expression),"%1.2f / %1.2f",a,b);ArithmeticValue(expression,0,0,a/b);snprintf(expression,sizeof(expression),"(%1.2f >= %1.2f) || (%1.2f == 0.0)",a,b,a);ArithmeticValue(expression,0,0,a>=b||a==0);snprintf(expression,sizeof(expression),"%1.2f ? %1.2f : 3.0",a,b);ArithmeticValue(expression,0,0,a?b:3);count+=4;}Check(count==(original?4536:5184),"complete ordinary integer/float arithmetic corpus");}
static void ArithmeticBoundary(int proof){char expression[1024];unsigned long minimum=(unsigned long)LONG_MAX+1UL;int width=sizeof(long)*CHAR_BIT;switch(proof){case 0:snprintf(expression,sizeof(expression),"%ld + 1",LONG_MAX);ArithmeticBad(expression,1);break;case 1:snprintf(expression,sizeof(expression),"%lu - 1",minimum);ArithmeticBad(expression,1);break;case 2:snprintf(expression,sizeof(expression),"%ld * 2",LONG_MAX);ArithmeticBad(expression,1);break;case 3:snprintf(expression,sizeof(expression),"%lu / -1",minimum);ArithmeticBad(expression,1);break;case 4:snprintf(expression,sizeof(expression),"%lu %% -1",minimum);ArithmeticBad(expression,1);break;case 5:snprintf(expression,sizeof(expression),"1 << %d",width);ArithmeticBad(expression,1);break;case 6:ArithmeticBad("1 >> -1",1);break;case 7:ArithmeticValue("-1 << 1",1,-2,0);break;case 8:ArithmeticValue("-2147483648",1,INT_MIN,0);break;case 9:snprintf(expression,sizeof(expression),"1 << %d",width-1);ArithmeticValue(expression,1,LONG_MIN,0);break;case 10:snprintf(expression,sizeof(expression),"%ld.0 * 2.0",LONG_MAX);ArithmeticValue(expression,0,0,(double)LONG_MAX*2);break;case 11:ArithmeticValue("1.0 / 0.5",0,0,2);break;case 12:{char value[256];memset(value,'9',200);strcpy(value+200,".0");snprintf(expression,sizeof(expression),"(%s * %s) > 0.0",value,value);ArithmeticBad(expression,0);break;}case 13:{char value[512];memset(value,'9',400);strcpy(value+400,".0");ArithmeticBad(value,0);break;}case 14:ArithmeticBad("1 << -1",1);break;default:ArithmeticBad("1 >> 999999",1);break;}}
static void ArithmeticWideCondition(void){if(sizeof(long)>sizeof(int)){char expression[128];unsigned long word=(unsigned long)UINT_MAX+1UL;snprintf(expression,sizeof(expression),"%lu ? 1 : 3",word);ArithmeticValue(expression,1,1,0);}}
int main(int argc,char **argv){if(argc>1){int proof=atoi(argv[1]);if(proof<16)ArithmeticBoundary(proof);else if(proof==17)ArithmeticWideCondition();else ArithmeticGoldens(1);return 0;}ArithmeticGoldens(0);ArithmeticWideCondition();{int proof;for(proof=0;proof<16;proof++)ArithmeticBoundary(proof);}ArithmeticValue("-2 >> 1",1,-1,0);ArithmeticValue("-1 >> 0",1,-1,0);ArithmeticValue("0 << 0",1,0,0);ArithmeticValue("1 << 3",1,8,0);ArithmeticValue("1.0 / 0.25",0,0,4);ArithmeticBad("1.0 / 0.0",0);ArithmeticBad("1 / 0",1);ArithmeticBad("1 % 0",1);puts("Real expression overflow/trap guards, native word shifts, fractional division and 5184 stock values passed (issue #48)");return 0;}
